public class Singleton {
    // The volatile keyword is mandatory post-Java 5 to prevent instruction reordering
    private static volatile Singleton instance;

    private Singleton() {
        // Private constructor initialization logic
    }

    public static Singleton getInstance() {
        // First check (no locking overhead for already-initialized instances)
        if (instance == null) {
            synchronized (Singleton.class) {
                // Second check under lock
                if (instance == null) {
                    instance = new Singleton();
                }
            }
        }
        return instance;
    }
}
